Read the module below and produce a smell inventory: name each smell with the track's vocabulary, locate it, and say why it raises change-cost. Then self-check against the model.<br/><pre>function placeOrder(o: any): string {
  let t = 0;
  for (const i of o.lines) t += i.price * i.qty;   // money as number
  t = t + t * 0.07;                                 // tax 0.07, also in invoice.ts
  if (o.kind === 'gift')   t -= 5;                  // type switch...
  else if (o.kind === 'sub') t *= 0.8;              // ...growing
  save(`UPDATE acct SET bal=${t}`);                 // persistence inlined
  return `&lt;b&gt;${t.toFixed(2)}&lt;/b&gt;`;              // HTML inlined
}</pre>

